import argparse,hashlib,json,pathlib,sys
P=pathlib.Path(__file__).resolve().parent
D=lambda b:hashlib.sha256(b).hexdigest()
def check(src,out):
 q=json.loads((src/'request.json').read_text());p=json.loads((src/'policy.json').read_text());e=json.loads((src/'evidence.json').read_text());raw=(src/'artifact.bin').read_bytes(); canonical=lambda x:(json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False)+'\n').encode();a=e.get('approval') or {};v=e.get('provenance') or {};t=e.get('tests') or []
 tests=all(sum(x.get('name')==name and x.get('status')=='PASS' for x in t if isinstance(x,dict))==1 and sum(x.get('name')==name for x in t if isinstance(x,dict))==1 for name in ['format','unit']);valid=all(isinstance(q.get(k),str) and q[k] for k in ['candidate_id','artifact_sha256','destination','policy_sha256']);ok=bool(valid and D(raw)==q.get('artifact_sha256') and v.get('artifact_sha256')==D(raw) and v.get('candidate_id')==q.get('candidate_id') and v.get('source')=='fixture-source-v1' and tests and a.get('role')=='synthetic-reviewer' and all(a.get(k)==q.get(k) for k in ['candidate_id','artifact_sha256','destination','policy_sha256']) and q.get('destination')==p.get('destination')=='synthetic/releases/v1' and q.get('policy_sha256')==D(canonical(p)))
 decision=json.loads((out/'06_decision.json').read_text()); hashes=json.loads((P/'expected_hashes.json').read_text()); values={n:D((out/n).read_bytes()) for n in hashes}; return {'expected_decision':'ELIGIBLE' if ok else 'HOLD','decision_agrees':decision['decision']==('ELIGIBLE' if ok else 'HOLD'),'expected_hashes_match':values==hashes,'status':'PASS' if decision['decision']==('ELIGIBLE' if ok else 'HOLD') and values==hashes else 'FAIL'}
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--src',type=pathlib.Path,default=P);a.add_argument('--out',type=pathlib.Path,required=True);x=a.parse_args();result=check(x.src,x.out);print(json.dumps(result,sort_keys=True));sys.exit(0 if result['status']=='PASS' else 1)
